const copyText = async (text: string) => {
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    document.body.appendChild(textarea);
    textarea.select();
    document.execCommand('copy');
    document.body.removeChild(textarea);
  }
};

function StatusPill({ status }: { status: AppStatus | '成功' | '失败' | '处理中' | '已授权' | '待授权' }) {
  const styles = {
    运行中: 'bg-[#eaf8f1] text-[#23865d]',
    已停用: 'bg-[#f1f3f6] text-[#7b8491]',
    草稿: 'bg-[#fff7e5] text-[#b57b17]',
    成功: 'bg-[#eaf8f1] text-[#23865d]',
    失败: 'bg-[#fff0ee] text-[#d95146]',
    处理中: 'bg-[#edf4ff] text-[#4d86d0]',
    已授权: 'bg-[#eaf8f1] text-[#23865d]',
    待授权: 'bg-[#fff7e5] text-[#b57b17]',
  } as const;
  return <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-medium ${styles[status]}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{status}</span>;
}

function MiniBars({ active = 5 }: { active?: number }) {
  const bars = [35, 48, 42, 68, 57, 84, 73, 91, 76, 98, 87, 100];
  return <div className="flex h-[70px] items-end gap-1.5">{bars.map((height, index) => <span key={index} style={{ height: `${height * 0.7}px` }} className={`min-w-0 flex-1 rounded-t-[4px] ${index >= bars.length - active ? 'bg-[#eb5b4d]' : 'bg-[#f7d4ce]'}`} />)}</div>;
}

